"""Bundle the pinned Lean VS Code input engine as a dependency-free browser module."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
vendor = ROOT / 'assets/web/vendor/lean-unicode-input'
target = ROOT / 'assets/web/lean-unicode.js'
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--check', action='store_true')
args = parser.parse_args()
parts = ['''// Generated by scripts/build_unicode_input.py; do not edit.
// @leanprover/unicode-input 0.1.12, Apache-2.0.
// Upstream sources, license, and provenance: vendor/lean-unicode-input/.
const factories = {
''']
for name in ['Range', 'TrackedAbbreviation', 'AbbreviationProvider', 'AbbreviationRewriter']:
    source = (vendor / (name + '.js')).read_text(encoding='utf-8')
    source = '\n'.join(line for line in source.splitlines() if not line.startswith('//# sourceMappingURL='))
    parts.append(json.dumps('./' + name) + ': (module, exports, require) => {\n' + source + '\n},\n')
table = json.loads((vendor / 'abbreviations.json').read_text(encoding='utf-8'))
parts.append('};\nconst cache = {"./abbreviations.json": {exports: ' + json.dumps(table, ensure_ascii=False) + '}};\n')
parts.append('''function require(name) {
  if (!cache[name]) {
    const module = cache[name] = {exports: {}};
    factories[name](module, module.exports, require);
  }
  return cache[name].exports;
}
export const {Range} = require('./Range');
export const {AbbreviationProvider} = require('./AbbreviationProvider');
export const {AbbreviationRewriter} = require('./AbbreviationRewriter');
''')
result = ''.join(parts)
if args.check:
    assert target.read_text(encoding='utf-8') == result, 'Regenerate lean-unicode.js'
else:
    target.write_text(result, encoding='utf-8', newline='\n')
print(f'Checked {len(table)} VS Code abbreviations.' if args.check else f'Bundled {len(table)} VS Code abbreviations.')
